INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7459665, 1182646, 96751, '<td valign="top">Wonderful find. Except for the shoes, this could definitely be a period piece.</td>', 'Wonderful find. Except for the shoes, this could definitely be a period piece.', '2016-06-10 01:11:08.000000', NULL, 1),
(7459666, 1182600, 96751, '<td valign="top">The redneck version :)</td>', 'The redneck version :)', '2016-06-10 01:12:39.000000', NULL, 1),
(7459669, 1182629, 96751, '<td valign="top">I''m dying here. The thought of sheep with a banana is just sending me over the edge. Love the inquisitiveness, and the spectator with the distant lamb behind him. Marvelous image.</td>', 'I''m dying here. The thought of sheep with a banana is just sending me over the edge. Love the inquisitiveness, and the spectator with the distant lamb behind him. Marvelous image.', '2016-06-10 01:15:30.000000', NULL, 1),
(7459670, 1182613, 96751, '<td valign="top">Glorious still life. A bit too vibrant to be Manet, but really beautiful.</td>', 'Glorious still life. A bit too vibrant to be Manet, but really beautiful.', '2016-06-10 01:21:54.000000', NULL, 1),
(7459671, 1182644, 96751, '<td valign="top">Hmmm, not getting the connection at all...</td>', 'Hmmm, not getting the connection at all...', '2016-06-10 01:23:02.000000', NULL, 1),
(7459672, 1182483, 96751, '<td valign="top">Lovely. Not sure I like such a dark shadow on the left side of her face.</td>', 'Lovely. Not sure I like such a dark shadow on the left side of her face.', '2016-06-10 01:28:59.000000', NULL, 1),
(7459673, 1182656, 96751, '<td valign="top">The colors are right; not digging the blur.</td>', 'The colors are right; not digging the blur.', '2016-06-10 01:29:57.000000', NULL, 1),
(7459708, 1182630, 101668, '<td valign="top">Nailed it. Good shot Meets challenge well</td>', 'Nailed it. Good shot Meets challenge well', '2016-06-10 07:48:02.000000', NULL, 1),
